#!/data/data/com.termux/files/usr/bin/bash
# Google TV Home - one-key home switch (packed build: the source is not readable here).
# Every use is exactly as before, only the file's insides are packed:
#   TV=192.168.168.161 bash sethome-tv.sh
#   TV=192.168.168.161 bash sethome-tv.sh -s restore
#   TV=192.168.168.161 bash sethome-tv.sh -s repair
__p=''
if printf 'AAAA' | base64 -d >/dev/null 2>&1; then __D="base64 -d";
elif printf 'AAAA' | openssl base64 -d >/dev/null 2>&1; then __D="openssl base64 -d";
else __D="busybox base64 -d"; fi
if command -v gzip >/dev/null 2>&1; then __G="gzip -dc"; else __G="busybox gunzip -c"; fi
__s="$(printf '%s' "$__p" | tr 'TBCYxA9hK6H7Vit5EN+nj3fvkaD=pemZ/MzU0PGlXwIgOq1JQ2RyFbs8ruLSdWoc4' 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=' | $__D | $__G)"
if [ -z "$__s" ]; then
  echo "cannot unpack (needs base64 and gzip; in Termux: pkg install gzip)" >&2
  exit 1
fi
unset __p __D __G
eval "$__s"
